// Compute CODE_CATEGORIES from CODE_LIBS array
const CODE_CATEGORIES = {};
CODE_LIBS.forEach(function (l) {
  if (!CODE_CATEGORIES[l.category]) {
    CODE_CATEGORIES[l.category] = { count: 0 };
  }
  CODE_CATEGORIES[l.category].count++;
});
